import{_ as n,C as o,o as r,c as s,ag as t,E as i}from"./chunks/framework.D1ek-kcM.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1788349408000}'),l={name:"getting-started/introduction.md"};function d(h,e,p,c,u,m){const a=o("ImagePopup");return r(),s("div",null,[e[0]||(e[0]=t('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://bagisto.com/en/laravel-multi-tenant-saas/" target="_blank" rel="noreferrer">Multi-Tenant eCommerce</a> in Bagisto lets you run a SaaS platform where many merchants create and manage their own individual stores under a single system. Each merchant — a <strong>tenant</strong> — gets a dedicated storefront and admin panel, while you, the platform owner, manage the infrastructure, subscription plans, and revenue from one place.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Who the two audiences of the platform are</li><li>What a super admin controls and what a tenant controls</li><li>Where to go next for each task</li></ul></div><h2 id="two-panels-two-audiences" tabindex="-1">Two panels, two audiences <a class="header-anchor" href="#two-panels-two-audiences" aria-label="Permalink to &quot;Two panels, two audiences&quot;">​</a></h2><p>The platform is run from two separate panels.</p><ul><li>The <strong>Super Admin panel</strong> is where you oversee every tenant, subscription plan, and platform-wide setting.</li><li>The <strong>Tenant Admin panel</strong> is a Bagisto-like backend each merchant uses to run their own store.</li></ul>',6)),i(a,{src:"/images/introduction/multi-tenant.webp",alt:"Multi-tenant SaaS platform overview"}),e[1]||(e[1]=t('<h2 id="what-the-super-admin-does" tabindex="-1">What the super admin does <a class="header-anchor" href="#what-the-super-admin-does" aria-label="Permalink to &quot;What the super admin does&quot;">​</a></h2><p>The super admin is the top authority on the platform. From the Super Admin panel you can:</p><ul><li><strong>Manage tenants</strong> — register merchants, view their store insights, edit them, and sign in as any tenant. See <a href="/super-admin/tenant-management">Tenant Management</a>.</li><li><strong>Sell subscriptions</strong> — create plans, track purchased plans, and review invoices. See <a href="/subscriptions/plan-management">Plan Management</a>.</li><li><strong>Run the platform</strong> — manage agents and roles, currencies, exchange rates, webhooks, and themes. See <a href="/settings/agents-and-roles">Agents &amp; Roles</a>.</li><li><strong>Publish content</strong> — manage CMS pages and platform-wide configuration. See <a href="/content/cms-pages">CMS Pages</a>.</li></ul><h2 id="what-a-tenant-does" tabindex="-1">What a tenant does <a class="header-anchor" href="#what-a-tenant-does" aria-label="Permalink to &quot;What a tenant does&quot;">​</a></h2><p>A tenant signs up, gets a storefront and admin panel provisioned automatically, and starts selling. A merchant manages products, categories, orders, and customers, chooses a storefront theme allowed by their plan, and reviews their own subscription and invoices. See <a href="/tenants/registration">Registration &amp; Sign-in</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New to the platform? If you run the SaaS, start with the <a href="/super-admin/dashboard">Super Admin Dashboard</a>. If you&#39;re a merchant setting up a store, start with <a href="/tenants/registration">Registration &amp; Sign-in</a>.</p></div>',6))])}const w=n(l,[["render",d]]);export{f as __pageData,w as default};
